static wmOperatorStatus file_open_blend_exec(bContext *C, wmOperator *op)
{
  char filepath[FILE_MAX];
  RNA_string_get(op->ptr, "filepath", filepath);

  if (!BLI_path_extension_check(filepath, ".blend")) {
    BKE_report(op->reports, RPT_ERROR, "Not a .blend file");
    return OPERATOR_CANCELLED;
  }

  return WM_file_read(C, filepath, true, op->reports) ? OPERATOR_FINISHED : OPERATOR_CANCELLED;
}

static wmOperatorStatus file_open_blend_invoke(bContext *C, wmOperator *op, const wmEvent *event)
{
  ED_fileselect_ensure_default_filepath(C, op, ".blend");
  return WM_operator_filesel(C, op, event);
}

void FILE_OT_open_blend(wmOperatorType *ot)
{
  /* identifiers */
  ot->name = "Open Blend File";
  ot->description = "Open a .blend file";
  ot->idname = "FILE_OT_open_blend";

  /* api callbacks */
  ot->exec = file_open_blend_exec;
  ot->invoke = file_open_blend_invoke;
  ot->poll = WM_operator_winactive;

  /* flags */
  ot->flag = OPTYPE_REGISTER | OPTYPE_UNDO;

  /* properties */
  WM_operator_properties_filesel(ot,
                                FILE_TYPE_FOLDER | FILE_TYPE_BLENDER,
                                FILE_BLENDER,
                                FILE_OPENFILE,
                                WM_FILESEL_FILEPATH | WM_FILESEL_SHOW_PROPS,
                                FILE_DEFAULTDISPLAY,
                                FILE_SORT_DEFAULT);
}

